```cpp
#include <vector>
#include <unordered_set>
#include <queue>
#include <string>
#include <tuple>

std::vector<std::tuple<int, int>> getKnightMoves(int n, int r, int c) {
  std::vector<std::tuple<int, int>> positions {
    { r + 2, c + 1 },
    { r - 2, c + 1 },
    { r + 2, c - 1 },
    { r - 2, c - 1 },
    { r + 1, c + 2 },
    { r - 1, c + 2 },
    { r + 1, c - 2 },
    { r - 1, c - 2 }
  };

  std::vector<std::tuple<int, int>> inboundsPositions;
  for (std::tuple<int, int> pos : positions) {
    auto [newRow, newCol] = pos;
    if (0 <= newRow && newRow < n && 0 <= newCol && newCol < n) {
      inboundsPositions.push_back(pos);
    }
  }
  return inboundsPositions;
}

int knightAttack(int n, int kr, int kc, int pr, int pc) {
  std::unordered_set<std::string> visited;
  std::string startingKnightPos = std::to_string(kr) + "," + std::to_string(kc);
  visited.insert(startingKnightPos);
  std::queue<std::tuple<int, int, int>> queue;
  queue.push(std::tuple<int, int, int> { kr, kc, 0 });
  while (!queue.empty()) {
    auto [ r, c, step ] = queue.front();
    queue.pop(); 
    if (r == pr && c == pc) {
      return step;
    }
    std::vector<std::tuple<int, int>> neighbors = getKnightMoves(n, r, c);
    for (std::tuple<int, int> neighbor : neighbors) {
        auto [neighborRow, neighborCol] = neighbor;
      std::string stringNeighbor = std::to_string(neighborRow) + "," + std::to_string(neighborCol);
      if (visited.count(stringNeighbor) == 0) {
        visited.insert(stringNeighbor);
        queue.push(std::tuple<int, int, int> { neighborRow, neighborCol, step + 1 });
      }
    }
  }
  return -1;
}
```

- n = length of the board
- Time: O(n^2)
- Space: O(n^2)
